import{_ as l,a0 as a,w as p,s as g,I as r,x as o,a1 as i,A as e,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"Spritz 12 年前融资 350 万做快速阅读，今天这事归 AI 管了 | LCTT x X-CMD","titleTemplate":false,"description":"2014 年 Spritz 这家「RSVP 快速阅读」公司融了 350 万美元种子轮，TechCrunch 报道后 ReadWrite 整理了 Linux 上 4 个快速阅读工具。12 年后看，Spritz 倒闭，RSVP 被 AI 摘要彻底取代。","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Spritz 12 年前融资 350 万做快速阅读，今天这事归 AI 管了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2014 年 Spritz 这家「RSVP 快速阅读」公司融了 350 万美元种子轮，TechCrunch 报道后 ReadWrite 整理了 Linux 上 4 个快速阅读工具。12 年后看，Spritz 倒闭，RSVP 被 AI 摘要彻底取代。"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/How to speed read on Linux","title":"Spritz 12 年前融资 350 万做快速阅读，今天这事归 AI 管了","tag":"201405","desc":"2014 年 Spritz 这家「RSVP 快速阅读」公司融了 350 万美元种子轮，TechCrunch 报道后 ReadWrite 整理了 Linux 上 4 个快速阅读工具。12 年后看，Spritz 倒闭，RSVP 被 AI 摘要彻底取代。"},"relativePath":"201405/How to speed read on Linux.md","filePath":"[post].md"}'),S={name:"201405/How to speed read on Linux.md"};function d(u,t,P,m,T,A){const n=a("Link");return p(),g("div",null,[t[13]||(t[13]=r("h1",{id:"spritz-12-年前融资-350-万做快速阅读-今天这事归-ai-管了",tabindex:"-1"},[o("Spritz 12 年前融资 350 万做快速阅读，今天这事归 AI 管了 "),r("a",{class:"header-anchor",href:"#spritz-12-年前融资-350-万做快速阅读-今天这事归-ai-管了","aria-label":"Permalink to “Spritz 12 年前融资 350 万做快速阅读，今天这事归 AI 管了”"},"​")],-1)),r("blockquote",null,[r("p",null,[t[1]||(t[1]=o("老文新评 #032 · ",-1)),i(n,{href:"http://techcrunch.com/2014/03/10/spritz-seed/",rel:"nofollow noopener"},{default:e(()=>[...t[0]||(t[0]=[o("techcrunch.com",-1)])]),_:1}),t[2]||(t[2]=o(" · 2014-05-01",-1))])]),t[14]||(t[14]=s('<h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to “一句话总结”">​</a></h2><p>Spritz 12 年前想做「让你读得更快」的工具——今天 AI 直接「替你读完」，RSVP 这个品类彻底消失，Spread0r、Chrome Spread、书签 Squirt、开源 Zethos 全进了开源墓园。</p><h2 id="文章讲了啥" tabindex="-1">文章讲了啥 <a class="header-anchor" href="#文章讲了啥" aria-label="Permalink to “文章讲了啥”">​</a></h2><p>2014 年 3 月，Spritz 这家波士顿公司融了 350 万美元种子轮，做 RSVP（rapid serial visual presentation）快速阅读 API——把单词一个接一个钉在屏幕的同一个位置，让眼球不再移动，被吹捧为「阅读的未来」。TechCrunch 报道后，ReadWrite 顺势整理了 Linux 上 4 个快速阅读工具：</p><ul><li><strong>Spread0r</strong> —— Perl + GTK2 写的 GPL 软件，原名 Gritz，从 GitHub 拉源码运行，最高 1000 词/分</li><li><strong>Spread</strong> —— Chrome 浏览器扩展，选中网页文本右键「Spreed selected text」，可在新窗口里 RSVP 阅读，速度最高 4000 词/分</li><li><strong>Squirt</strong> —— 书签栏小工具（非扩展），点击后在当前页弹出白色面板阅读，UI 漂亮，速度上限 4000+ 词/分</li><li><strong>Zethos</strong> —— 开源 JavaScript 项目，给开发者自己 fork 出 RSVP 应用的起点</li></ul><p>这 4 个工具的共同点是「单词一个一个出现」——让眼睛不再左右移动。文章最后吐槽「小心你的大脑别被烧焦」——12 年后这反而成了最准确的隐喻。</p><h2 id="_12-年后重读" tabindex="-1">12 年后重读 <a class="header-anchor" href="#_12-年后重读" aria-label="Permalink to “12 年后重读”">​</a></h2><p>12 年后再看 Spritz 这条线，<strong>最讽刺的是它被自己的「目标用户」淘汰</strong>。Spritz 想让人「读得更快」，但 2026 年的解决方案不是让人读得更快，而是<strong>让 AI 替人读完</strong>。GPT-4 / Claude 3 / Gemini 都能在 5 秒内读完一篇 5000 字长文并生成 200 字摘要，附带 5 个核心观点和待追问问题。</p><p>这背后的范式转换很有意思：</p><ul><li><strong>RSVP</strong> 是「加速人的阅读速度」——人还是主导</li><li><strong>AI 摘要</strong> 则是「跳过人的阅读」——人退到提问者位置</li></ul><p>Spread0r 这种 2014 年工具的「亮点」是「1000 词/分」；2026 年的 AI 是「10000 字/秒」，且能回答「这段在说什么」。两种方案的目标都是「高效获取信息」，但 AI 路径根本不让人读。</p><p><strong>更值得玩味的是「注意力经济」这条线</strong>。Spritz 当年押注的「注意力稀缺」——12 年后注意力确实变成了稀缺资源，但解决方案不是 RSVP，而是<strong>TikTok 短视频</strong>。</p><p>一分钟一个视频、三秒一个钩子——这种节奏感反而和 Spritz 那种「一个词接一个词」有异曲同工之妙。区别是：RSVP 想保留「读完」的成就感，TikTok 索性把「读完」这件事整个消解了。</p><p><strong>Spread0r / Spritz 这种工具的真正继承者</strong>——是 NotebookLM 这种「AI 给你读」的方案。NotebookLM 把你的笔记、PDF、网页转成播客式对话，让两个 AI「讨论」内容给你听。这不是 RSVP（让你读），也不是纯文本摘要（让你看），是 <strong>AI 替你和替我讨论——你只负责听和追问</strong>。</p><p><strong>12 年间「读」这件事的 3 个阶段</strong>：</p><ul><li><strong>2014</strong>：人 + 工具（RSVP）—— 让眼睛动得少</li><li><strong>2020</strong>：人 + 工具（语音合成 + 音频）—— 让眼睛不用动</li><li><strong>2026</strong>：AI + AI（NotebookLM、AI 播客）—— 让人根本不用读</li></ul><p><strong>Spritz 当年犯的根本错误</strong>是：他们想解决「人读得慢」，但没意识到「人为什么要读」这个问题本身正在被 AI 替代。<strong>「快速阅读」的真正答案不是「读得快」，是「不用读」</strong>。</p><h2 id="那个被-spritz-漏掉的「注意力流向」" tabindex="-1">那个被 Spritz 漏掉的「注意力流向」 <a class="header-anchor" href="#那个被-spritz-漏掉的「注意力流向」" aria-label="Permalink to “那个被 Spritz 漏掉的「注意力流向」”">​</a></h2><p>回看 2014 年 Spritz 的整套逻辑——把单词钉在屏幕中央让眼睛不移动，节省眼球运动时间——<strong>这套设计的潜台词是「阅读是眼睛的体力活」</strong>。</p><p>12 年后回看，这个潜台词完全错。<strong>阅读从来不是眼睛的体力活，是大脑的认知活</strong>。RSVP 节省的那点眼球运动时间，对真正难懂的内容（论文、法律文书、代码）来说根本不是瓶颈——<strong>理解才是瓶颈</strong>。Spritz 让你 5 分钟扫完 5000 字，但你可能根本没懂它在说什么。</p><p><strong>更讽刺的是 Spritz 当年的「小心大脑被烧焦」警告</strong>——12 年后这反而成了最准确的预言：</p><ul><li><strong>Saccade（眼动）减少</strong> → 失去深度阅读能力</li><li><strong>碎片化阅读</strong> → 注意力只能维持 30 秒</li><li><strong>跳读（skimming）训练</strong> → 读完整本书的能力下降</li></ul><p>2026 年的研究（Common Sense Media、Pew Research、Microsoft Attention Spans 报告）反复发现：<strong>习惯 RSVP / 短视频 / TL;DR 摘要的人，深度阅读能力显著下降</strong>。这反而是 RSVP 范式的真正遗产——它<strong>训练了一代不会深度阅读的人</strong>。</p><p><strong>Spritz 真正的继承者不是「读得更快」的工具，而是「帮用户判断值不值得读」的工具</strong>：</p><ul><li>Pocket / Matter —— 稍后读（但变成「永不读」）</li><li>Readwise Reader —— 强调深度阅读和笔记</li><li>NotebookLM —— 替用户读 + 总结</li><li>AI 阅读助手（ChatGPT Read、Claude Connectors）—— 边读边问</li></ul><p><strong>12 年前 Spritz 的目标</strong>「让你 5 分钟读完一篇文章」——<strong>12 年后被 AI 实现得过于完美</strong>。一篇 5000 字的长文，AI 5 秒就能总结成 200 字 + 5 个观点 + 3 个待追问问题。<strong>代价是：人不再深度阅读了</strong>。</p><p>Spritz 当年那个 RSVP 想法本身不算错——但<strong>他没意识到自己是在和「AI 摘要」这条更根本的解决方案赛跑</strong>。2014 年 AI 还没成熟，Spritz 拿到了 350 万美元种子轮；2017 年 Spritz 倒闭，被 Samsung 收购后无疾而终；2026 年 RSVP 这个品类彻底消失——<strong>「读得快」这件事，被「不用读」彻底替代</strong>。</p><hr><p><strong>出处</strong></p>',29)),r("ul",null,[r("li",null,[t[4]||(t[4]=r("strong",null,"原文",-1)),t[5]||(t[5]=o("（ARR 风险）：",-1)),i(n,{href:"http://techcrunch.com/2014/03/10/spritz-seed/",rel:"nofollow noopener"},{default:e(()=>[...t[3]||(t[3]=[o("techcrunch.com",-1)])]),_:1})]),r("li",null,[t[7]||(t[7]=r("strong",null,"LCTT 译稿源档",-1)),t[8]||(t[8]=o("：",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject/blob/master/sources/tech/"},{default:e(()=>[...t[6]||(t[6]=[o("github.com/LCTT/TranslateProject",-1)])]),_:1})]),r("li",null,[t[10]||(t[10]=r("strong",null,"原译",-1)),t[11]||(t[11]=o("：",-1)),i(n,{href:"https://lctt.x-cmd.com/201405/How%20to%20speed%20read%20on%20Linux/"},{default:e(()=>[...t[9]||(t[9]=[o("linux.cn",-1)])]),_:1})]),t[12]||(t[12]=r("li",null,[r("strong",null,"发布"),o("：2014-05-01")],-1))]),t[15]||(t[15]=s('<hr><h2 id="这些观点今天还成立吗" tabindex="-1">这些观点今天还成立吗？ <a class="header-anchor" href="#这些观点今天还成立吗" aria-label="Permalink to “这些观点今天还成立吗？”">​</a></h2><ul><li>❌ <strong>RSVP 是提升阅读速度的方案</strong> —— 已被 AI 摘要替代，没人再用 RSVP 工具</li><li>❌ <strong>Spritz 是这条赛道的领跑者</strong> —— Spritz 2017 年倒闭，被 Samsung 收购后无疾而终</li><li>⚠️ <strong>最高 1000-4000 词/分是目标</strong> —— 现在 AI 1 秒读 1 万字，提问还能继续追问</li><li>⚠️ <strong>极客愿意为生产力工具付费</strong> —— 仍成立，但订阅制 + AI 增值是主流</li><li>⚠️ <strong>移动设备需要「快速阅读」</strong> —— 移动设备的解决方案变成音频（Audible / 播客）+ AI 摘要</li><li>⚠️ <strong>注意力经济会被工具改进</strong> —— 注意力经济反而被短视频 / TikTok 改造得更碎片</li></ul>',3))])}const R=l(S,[["render",d]]);export{I as __pageData,R as default};
